insert overwrite
    srdi_mart.dwd_sr_data_warehouse_video_unify_full_link_log_1h partition (
        regional_date = ${regional_date}
        ,regional_hour = ${regional_hour}
        ,country = ${grass_region}
    )
select
    -- common fields
    request_id
    ,session_id
    ,user_id
    ,entrance
    ,ab_sign
    ,ads_id as ads_id
    ,item_id as item_id
    ,shop_id as shop_id
    ,video_id as video_id
    ,item_type
    ,if (recall_info is not null, true, false) as is_recall
    ,if (prerank_info is not null, true, false) as is_prerank
    ,if (rank_info is not null, true, false) as is_rank
    ,if (mixrank_info is not null, true, false) as is_mixrank
    ,if (final_stage = 'DISPATCH', true, false) as is_dispatch
    ,is_sampled
    -- recall stage
    ,case
        when from_organic = true and from_ads = true then 3
        when from_ads = true then 1
        when from_organic = true then 2
        else 0
