    ,transform (recall_strategies, x -> cast(x.queue_id as int)) as recall_queues
    ,transform (recall_strategies, x -> cast(x.score as float)) as queue_scores
    ,ads_info_api_error
    ,if (final_stage != 'RECALL', 'NOT_FILTERED', remove_reason) as recall_remove_reason
    -- prerank stage
    ,prerank_score
    ,prerank_position
    ,if (final_stage != 'PRERANK', 'NOT_FILTERED', remove_reason) as prerank_remove_reason
    -- rank stage
    ,rank_score
    ,rank_position
    ,rank_pctr
    ,rank_pcr
    ,rank_broad_pcr
    ,rank_ecpm
    ,rank_ecpm_weight
    ,rank_estimated_gmv
    ,bidding_api_error
    ,if (final_stage != 'RANK', 'NOT_FILTERED', remove_reason) as rank_remove_reason
    -- mixrank stage
    ,mixrank_score
    ,mixrank_position
    ,mixrank_item_price
    ,mixrank_pctr
    ,mixrank_pcr
    ,mixrank_broad_pcr
    ,mixrank_ecpm
    ,mixrank_ecpm_weight
    ,mixrank_estimated_gmv
    ,mixrank_porg
    ,deduction_api_error
    ,if (final_stage != 'MIXRANK', 'NOT_FILTERED', remove_reason) as mixrank_remove_reason
    -- dispatch stage
    ,dispatch_position
    -- virtual item
    -- ads ext
    ,ads_recall_ext
    ,ads_info_ext
    ,ads_bid_ext
